function validate(d){const errors=[];for(const f of fields){const v=d[f.id];if(v===null||v===undefined||v==='')continue;if(f.options){if(!f.options.some(o=>o[0]===v))errors.push(f.id);}else if(!Number.isFinite(v)||v<f.min||v>f.max||(f.step===1&&!Number.isInteger(v)))errors.push(f.id);}if(!Number.isInteger(d.age))errors.push('age');if(!['general','restricted'].includes(d.context))errors.push('context');if(d.rest!=null&&d.rest>=(d.max??(208-.7*d.age)))errors.push('rest');return [...new Set(errors)];}
function habitScore(d){
const alcoholDeduction = d.alcohol >= 20 ? 15 : d.alcohol >= 15 ? 10 : d.alcohol >= 10 ? 5 : 0;
const cigaretteDeduction = d.cigarettes > 15 ? 15 : d.cigarettes >= 10 ? 10 : d.cigarettes >= 5 ? 5 : 0;
const items=[
['Schlaf: mindestens 7 Stunden','Sleep: at least 7 hours',['sleep'],d.sleep>=7],
['Meistens erholt nach dem Schlaf','Usually rested after sleep',['quality'],d.quality==='yes'],
['Ausdauer: mindestens 150 Äquivalent-Minuten/Woche','Aerobic activity: at least 150 equivalent minutes/week',['moderate','vigorous'],d.moderate+2*d.vigorous>=150],
['Krafttraining: mindestens 2 Tage/Woche','Strength training: at least 2 days/week',['strength'],d.strength>=2],
['Sitzzeiten regelmäßig unterbrechen','Regular breaks from sitting',['breaks'],d.breaks==='yes'],
['Gemüse und Obst: mindestens 400 g/Tag','Fruit and vegetables: at least 400 g/day',['plants'],d.plants>=400],
['Regelmäßig Vollkorn und Hülsenfrüchte','Regular whole grains and legumes',['whole'],d.whole==='often'],
['Zigaretten pro Tag','Cigarettes per day',['cigarettes'],true,cigaretteDeduction],
['Keine Vapes','No vaping',['vape'],d.vape==='no'],
['Standardgläser Alkohol pro Woche','Standard alcoholic drinks per week',['alcohol'],true,alcoholDeduction]
].map(([de,en,keys,met,deduction=0])=>({de,en,known:keys.every(k=>d[k]!=null&&d[k]!==''),points:(met?10:0)-deduction,deduction}));
const answered=items.filter(x=>x.known).length;
const points = items.reduce((sum,item)=>sum+item.points,0);
return {items,answered,total:items.length,alcoholDeduction,cigaretteDeduction,
  value:answered===items.length&&d.context==='general'?Math.max(0,points):null};

}
function fitnessBonus(value,age,sex){
  const comparison=classifyVo2(value,age,sex);
  if(!comparison)return null;
  const referencePoints=comparison.band*5;
  const extra=value>=60?10:value>=50?5:0;
  return {...comparison,points:referencePoints+extra,referencePoints,extra};
}
